async (page) => {
  const K='50pj7fxprnzj2';
  const errs=[]; page.on('console', m=>{ if(m.type()==='error') errs.push(m.text()); }); page.on('pageerror', e=>errs.push('pageerror: '+e.message));
  await page.unrouteAll();
  await page.route('**/*', async route => {
    await route.continue({ headers: { ...route.request().headers(), 'baggage': 'sd-routing-key='+K, 'tracestate': 'sd-routing-key='+K } });
  });
  await page.goto('http://frontend.ctbench-hotrod.svc:8080/');
  await page.waitForLoadState('networkidle');
  const selects = page.locator('select');
  const opts = await selects.first().evaluate(s=>[...s.options].map(o=>({v:o.value,t:o.text})));
  await selects.nth(0).selectOption('1');
  await selects.nth(1).selectOption('123');
  await page.getByRole('button',{name:'Request Ride'}).click();
  await page.getByRole('button',{name:'Show Logs'}).click();
  await page.waitForTimeout(8000);
  const body = await page.locator('body').innerText();
  return {opts, errs, len:(await page.content()).length, body: body.slice(0,1500)};
}

